set-variable.value:
@{
      var caller = (string)context.Variables["caller"];
      var invocation = new [] { __CALLERS__ };
      var op = context.Operation.Id;
      if (new [] { "operator-drafts", "operator-draft-page", "operator-draft" }.Contains(op)) {
        return "__TARGET__" == "evidence-assessor" && caller == "operator-web";
      }
      if (new [] { "operator-releases", "operator-release-page", "operator-finding" }.Contains(op)) {
        return "__TARGET__" == "release-reviewer" && caller == "operator-web";
      }
      if (new [] { "operator-runs", "operator-run-page", "operator-run" }.Contains(op)) {
        return "__TARGET__" == "candidate-planner" && caller == "operator-web";
      }
      if (op == "findings-read") {
        return "__TARGET__" == "release-reviewer" && (caller == "candidate-planner" || caller == "briefing-author");
      }
      return invocation.Contains(caller) && new [] { "a2a", "status", "discovery", "mcp-post", "mcp-get", "mcp-delete" }.Contains(op);
    }

@{
          var body = context.Request.Body.As<JObject>(preserveContent: true);
          if ((string)body["jsonrpc"] != "2.0") { return false; }
          var method = (string)body["method"];
          if (new [] { "initialize", "notifications/initialized", "ping", "tools/list" }.Contains(method)) { return true; }
          return method == "tools/call" && body["params"] is JObject && new [] { "search_airports", "lookup_airport", "list_runways" }.Contains((string)body["params"]["name"]);
        }

@{
      var op = context.Operation.Id;
      if (op == "operator-draft") {
        return "/operator/runs/" + context.Request.MatchedParameters["runId"] + "/drafts/" + context.Request.MatchedParameters["draftId"] + "/versions/" + context.Request.MatchedParameters["version"];
      }
      if (op == "operator-drafts" || op == "operator-draft-page") {
        var path = "/operator/runs/" + context.Request.MatchedParameters["runId"] + "/drafts";
        return op == "operator-draft-page" ? path + "/page/" + context.Request.MatchedParameters["cursor"] : path;
      }
      if (op == "operator-releases" || op == "operator-release-page") {
        var path = "/operator/runs/" + context.Request.MatchedParameters["runId"] + "/releases";
        return op == "operator-release-page" ? path + "/page/" + context.Request.MatchedParameters["cursor"] : path;
      }
      if (op == "operator-finding") {
        return "/operator/runs/" + context.Request.MatchedParameters["runId"] + "/findings/" + context.Request.MatchedParameters["findingId"] + "/versions/" + context.Request.MatchedParameters["version"];
      }
      if (op == "operator-runs") { return "/operator/runs"; }
      if (op == "operator-run-page") { return "/operator/runs/page/" + context.Request.MatchedParameters["cursor"]; }
      if (op == "operator-run") { return "/operator/runs/" + context.Request.MatchedParameters["runId"]; }
      if (op == "a2a") { return "/a2a"; }
      if (op == "discovery") { return "/.well-known/agent-card.json"; }
      if (op.StartsWith("mcp-")) { return "/mcp"; }
      if (op == "status") { return "/operations/" + context.Request.MatchedParameters["operationId"]; }
      return "/findings/" + context.Request.MatchedParameters["findingId"] + "/versions/" + context.Request.MatchedParameters["version"];
    }

set-header.value:
@{
      var bytes = context.Request.Body == null ? new byte[0] : context.Request.Body.As<byte[]>(preserveContent: true);
      var hash = BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(bytes)).Replace("-", "").ToLowerInvariant();
      var canonical = String.Join("\n", new [] {
        "v1", "__KEY_ID__", context.Request.Headers.GetValueOrDefault("X-Citadel-Timestamp", ""),
        context.RequestId.ToString("N"), (string)context.Variables["caller"], "__TARGET__",
        context.Request.Method, (string)context.Variables["originPath"], hash
      });
      var key = Convert.FromBase64String("{{context-__TARGET__}}");
      return Convert.ToBase64String(new System.Security.Cryptography.HMACSHA256(key).ComputeHash(System.Text.Encoding.UTF8.GetBytes(canonical)));
    }
